INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, '¿Qué función se usa para sumar un rango de celdas?', 'opcion_multiple', '["PROMEDIO","SUMA","CONTAR","MAX"]', 'SUMA', 'SUMA agrega todos los números en un rango de celdas.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'La función BUSCARV sirve para:', 'opcion_multiple', '["Buscar verticalmente en una tabla","Buscar horizontalmente","Ordenar datos","Filtrar datos"]', 'Buscar verticalmente en una tabla', 'BUSCARV busca un valor en la primera columna y devuelve un valor en la misma fila.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, '¿Cuál es el resultado de =SI(A1>10,"Mayor","Menor") si A1=15?', 'opcion_multiple', '["Mayor","Menor","10","15"]', 'Mayor', 'Como 15>10 es VERDADERO, devuelve "Mayor".', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'La función PROMEDIO calcula:', 'opcion_multiple', '["La suma total","La media aritmética","El valor máximo","El valor mínimo"]', 'La media aritmética', 'Calcula el promedio (media aritmética) de los argumentos.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, '¿Qué símbolo se usa para referencias absolutas?', 'opcion_multiple', '["$","#","@","&"]', '$', '$A$1 crea una referencia absoluta que no cambia al copiar.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'La función CONTAR cuenta:', 'opcion_multiple', '["Todas las celdas","Solo celdas con números","Solo celdas con texto","Celdas vacías"]', 'Solo celdas con números', 'CONTAR solo cuenta celdas que contienen números.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, '=CONCATENAR(A1," ",B1) sirve para:', 'opcion_multiple', '["Sumar A1 y B1","Unir texto de A1 y B1","Restar A1 de B1","Dividir A1 entre B1"]', 'Unir texto de A1 y B1', 'Concatena (une) textos de diferentes celdas.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'La función MAX devuelve:', 'opcion_multiple', '["El valor mínimo","El valor máximo","El promedio","La suma"]', 'El valor máximo', 'Devuelve el valor más grande de un conjunto.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, '¿Qué hace la función MIN?', 'opcion_multiple', '["Busca el máximo","Busca el mínimo","Calcula promedio","Cuenta celdas"]', 'Busca el mínimo', 'Devuelve el valor más pequeño de un conjunto.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'La función HOY() devuelve:', 'opcion_multiple', '["La hora actual","La fecha actual","El día de la semana","El mes actual"]', 'La fecha actual', 'Devuelve la fecha actual del sistema.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, '¿Qué función cuenta celdas que cumplen un criterio?', 'opcion_multiple', '["CONTAR","CONTAR.SI","CONTARA","SUMAR.SI"]', 'CONTAR.SI', 'CONTAR.SI cuenta celdas que cumplen una condición específica.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'SUMAR.SI(A1:A10,">5") suma:', 'opcion_multiple', '["Todos los valores","Solo valores mayores a 5","Solo valores menores a 5","Valores iguales a 5"]', 'Solo valores mayores a 5', 'Suma solo las celdas que cumplen el criterio >5.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'La función SI anidada permite:', 'opcion_multiple', '["Una sola condición","Múltiples condiciones","Sin condiciones","Solo 2 condiciones"]', 'Múltiples condiciones', 'Permite evaluar múltiples condiciones una dentro de otra.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, '¿Qué hace la función Y()?', 'opcion_multiple', '["Devuelve VERDADERO si todas las condiciones son verdaderas","Devuelve VERDADERO si alguna es verdadera","Devuelve FALSO siempre","Suma condiciones"]', 'Devuelve VERDADERO si todas las condiciones son verdaderas', 'Y() devuelve VERDADERO solo si TODAS las condiciones son verdaderas.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'La función O() devuelve VERDADERO si:', 'opcion_multiple', '["Todas son verdaderas","Al menos una es verdadera","Ninguna es verdadera","Son iguales"]', 'Al menos una es verdadera', 'O() devuelve VERDADERO si ALGUNA condición es verdadera.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'BUSCARH busca:', 'opcion_multiple', '["Verticalmente","Horizontalmente","En diagonal","En 3D"]', 'Horizontalmente', 'BUSCARH busca en la primera fila y devuelve de la misma columna.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'La función COINCIDIR devuelve:', 'opcion_multiple', '["El valor buscado","La posición del valor","El texto","La suma"]', 'La posición del valor', 'Devuelve la posición relativa de un elemento en un rango.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'INDICE(matriz,fila,columna) sirve para:', 'opcion_multiple', '["Crear matriz","Obtener valor de una posición","Sumar matriz","Contar matriz"]', 'Obtener valor de una posición', 'Devuelve el valor de una celda en la intersección de fila y columna.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'La función TEXTO(A1,"dd/mm/aaaa"):', 'opcion_multiple', '["Convierte fecha a texto con formato","Suma fechas","Resta fechas","Compara fechas"]', 'Convierte fecha a texto con formato', 'Convierte un valor a texto con el formato especificado.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, '¿Qué hace ESPACIOS(A1)?', 'opcion_multiple', '["Agrega espacios","Elimina espacios extras","Cuenta espacios","Reemplaza espacios"]', 'Elimina espacios extras', 'Elimina todos los espacios del texto excepto los espacios simples entre palabras.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'BUSCARX es mejor que BUSCARV porque:', 'opcion_multiple', '["Es más rápida","Busca en cualquier dirección","Solo funciona en inglés","Es más antigua"]', 'Busca en cualquier dirección', 'BUSCARX puede buscar en cualquier dirección y es más flexible.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'La función FILTRAR() sirve para:', 'opcion_multiple', '["Ordenar datos","Filtrar datos dinámicamente","Eliminar datos","Copiar datos"]', 'Filtrar datos dinámicamente', 'Filtra un rango de datos basándose en criterios definidos.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'UNICOS() devuelve:', 'opcion_multiple', '["Valores duplicados","Valores únicos sin duplicados","La suma","El promedio"]', 'Valores únicos sin duplicados', 'Devuelve una lista de valores únicos de un rango.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'ORDENAR(matriz,columna,orden) sirve para:', 'opcion_multiple', '["Filtrar","Ordenar dinámicamente","Buscar","Sumar"]', 'Ordenar dinámicamente', 'Ordena el contenido de un rango o matriz.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'La función SECUENCIA(filas,columnas) genera:', 'opcion_multiple', '["Texto aleatorio","Una matriz de números secuenciales","Fechas","Gráficos"]', 'Una matriz de números secuenciales', 'Genera una lista de números secuenciales en una matriz.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'SI.ERROR(valor,valor_si_error) sirve para:', 'opcion_multiple', '["Crear errores","Manejar errores elegantemente","Ignorar errores","Multiplicar errores"]', 'Manejar errores elegantemente', 'Devuelve un valor personalizado si la fórmula genera un error.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'La función ELEGIR(num,valor1,valor2,...):', 'opcion_multiple', '["Elige un valor de la lista según el índice","Suma valores","Concatena valores","Ordena valores"]', 'Elige un valor de la lista según el índice', 'Selecciona un valor de la lista basándose en el número de índice.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'DESREF(celda,filas,columnas,alto,ancho) devuelve:', 'opcion_multiple', '["Una referencia desplazada","Un valor fijo","Un error","Texto"]', 'Una referencia desplazada', 'Devuelve una referencia a un rango desplazado desde una celda inicial.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'La función TASA() calcula:', 'opcion_multiple', '["Interés simple","Tasa de interés por periodo","Pago total","Valor futuro"]', 'Tasa de interés por periodo', 'Calcula la tasa de interés por periodo de una anualidad.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'PAGO(tasa,nper,va) calcula:', 'opcion_multiple', '["El pago periódico de un préstamo","El interés total","El capital","La tasa"]', 'El pago periódico de un préstamo', 'Calcula el pago de un préstamo basado en pagos constantes y tasa constante.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Una tabla dinámica sirve para:', 'opcion_multiple', '["Solo mostrar datos","Resumir y analizar grandes cantidades de datos","Eliminar datos","Crear gráficos"]', 'Resumir y analizar grandes cantidades de datos', 'Permite resumir, analizar, explorar y presentar datos de resumen.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Los campos de una tabla dinámica se organizan en:', 'opcion_multiple', '["Filas, columnas, valores y filtros","Solo filas y columnas","Solo valores","Solo filtros"]', 'Filas, columnas, valores y filtros', 'Cuatro áreas: Filtros, Columnas, Filas y Valores.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Para actualizar una tabla dinámica se debe:', 'opcion_multiple', '["Borrar y crear de nuevo","Hacer clic en Actualizar","Esperar automáticamente","Reiniciar Excel"]', 'Hacer clic en Actualizar', 'Se actualiza con clic derecho > Actualizar o pestaña Analizar > Actualizar.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'La segmentación de datos permite:', 'opcion_multiple', '["Filtrar visualmente tablas dinámicas","Ordenar datos","Sumar datos","Graficar datos"]', 'Filtrar visualmente tablas dinámicas', 'Botones visuales para filtrar datos en tablas dinámicas.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Un campo calculado en tabla dinámica permite:', 'opcion_multiple', '["Crear fórmulas personalizadas","Eliminar campos","Ocultar campos","Mover campos"]', 'Crear fórmulas personalizadas', 'Permite crear cálculos personalizados con los datos existentes.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Agrupar fechas en tabla dinámica permite:', 'opcion_multiple', '["Solo ver días","Agrupar por meses, trimestres, años","Eliminar fechas","Sumar fechas"]', 'Agrupar por meses, trimestres, años', 'Agrupa automáticamente por períodos de tiempo.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'El formato de número en valores de tabla dinámica:', 'opcion_multiple', '["No se puede cambiar","Se puede personalizar","Siempre es moneda","Siempre es porcentaje"]', 'Se puede personalizar', 'Se puede configurar el formato de número en Configuración de campo de valor.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Mostrar valores como en tabla dinámica permite:', 'opcion_multiple', '["Solo suma","Porcentajes, diferencias, acumulados","Solo promedio","Solo conteo"]', 'Porcentajes, diferencias, acumulados', 'Muestra valores como % del total, diferencia, ejecución, etc.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Una tabla dinámica conectada a Power Pivot permite:', 'opcion_multiple', '["Solo datos simples","Manejar millones de filas y relaciones","Solo texto","Solo gráficos"]', 'Manejar millones de filas y relaciones', 'Power Pivot permite modelos de datos avanzados con millones de filas.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Actualizar automáticamente al abrir el libro requiere:', 'opcion_multiple', '["Nada especial","Configurar propiedades de la tabla","Macro obligatoria","VBA complejo"]', 'Configurar propiedades de la tabla', 'En Opciones de tabla dinámica > marcar ''Actualizar al abrir el archivo''.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Un gráfico de líneas es ideal para:', 'opcion_multiple', '["Comparar categorías","Mostrar tendencias en el tiempo","Mostrar partes de un todo","Distribución de datos"]', 'Mostrar tendencias en el tiempo', 'Muestra tendencias y cambios a lo largo del tiempo.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Un gráfico circular muestra:', 'opcion_multiple', '["Tendencias","Partes de un todo (porcentajes)","Comparaciones","Distribución"]', 'Partes de un todo (porcentajes)', 'Muestra la contribución de cada valor al total.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Un histograma muestra:', 'opcion_multiple', '["Frecuencia de datos","Tendencias","Porcentajes","Relaciones"]', 'Frecuencia de datos', 'Muestra la distribución de frecuencia de los datos.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Los minigráficos (sparklines) son:', 'opcion_multiple', '["Gráficos grandes","Gráficos pequeños en una celda","Tablas","Fórmulas"]', 'Gráficos pequeños en una celda', 'Minigráficos que caben en una sola celda para mostrar tendencias.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Un gráfico combinado permite:', 'opcion_multiple', '["Solo un tipo de gráfico","Combinar dos tipos (ej. columnas y líneas)","Solo columnas","Solo líneas"]', 'Combinar dos tipos (ej. columnas y líneas)', 'Combina dos o más tipos de gráficos en uno solo.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'El eje secundario en gráficos sirve para:', 'opcion_multiple', '["Mostrar otra escala de valores","Eliminar datos","Ocultar datos","Sumar datos"]', 'Mostrar otra escala de valores', 'Permite graficar series con escalas muy diferentes.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Las etiquetas de datos muestran:', 'opcion_multiple', '["Solo el título","Valores específicos en el gráfico","Solo leyenda","Solo ejes"]', 'Valores específicos en el gráfico', 'Muestran los valores exactos en cada punto del gráfico.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Un gráfico de dispersión (XY) muestra:', 'opcion_multiple', '["Relación entre dos variables numéricas","Solo una variable","Texto","Fechas"]', 'Relación entre dos variables numéricas', 'Muestra la relación entre valores numéricos en dos series.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Los filtros de gráfico permiten:', 'opcion_multiple', '["No filtrar","Filtrar datos visibles en el gráfico","Eliminar gráfico","Copiar gráfico"]', 'Filtrar datos visibles en el gráfico', 'Filtran qué datos se muestran en el gráfico dinámicamente.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Un mapa 3D en Excel requiere:', 'opcion_multiple', '["Solo texto","Datos geográficos (países, ciudades)","Solo números","Solo fechas"]', 'Datos geográficos (países, ciudades)', 'Necesita datos geográficos para crear visualizaciones en mapa.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'El formato condicional permite:', 'opcion_multiple', '["Solo colorear","Aplicar formato basado en condiciones","Solo bordes","Solo fuentes"]', 'Aplicar formato basado en condiciones', 'Aplica formato automáticamente cuando se cumplen condiciones.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Las barras de datos en formato condicional:', 'opcion_multiple', '["Son gráficos separados","Muestran barras dentro de las celdas","Son tablas","Son fórmulas"]', 'Muestran barras dentro de las celdas', 'Muestran barras proporcionales al valor dentro de la celda.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Las escalas de color aplican:', 'opcion_multiple', '["Un solo color","Degradado de colores según valor","Solo rojo","Solo verde"]', 'Degradado de colores según valor', 'Aplica un degradado de 2 o 3 colores según el valor.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Los conjuntos de iconos muestran:', 'opcion_multiple', '["Solo números","Iconos según rangos de valores","Solo texto","Solo fechas"]', 'Iconos según rangos de valores', 'Muestra iconos (semáforos, flechas, etc.) según el valor.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Una fórmula en formato condicional permite:', 'opcion_multiple', '["Condiciones simples","Condiciones personalizadas complejas","Sin condiciones","Solo igualdad"]', 'Condiciones personalizadas complejas', 'Permite crear reglas personalizadas con fórmulas.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Resaltar celdas que contienen texto específico usa:', 'opcion_multiple', '["Solo números","Regla de texto que contiene","Solo fechas","Solo colores"]', 'Regla de texto que contiene', 'Regla predefinida para buscar texto específico.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Los valores duplicados se pueden resaltar con:', 'opcion_multiple', '["No se puede","Formato condicional > Valores duplicados","Solo manualmente","Solo con VBA"]', 'Formato condicional > Valores duplicados', 'Regla predefinida para identificar duplicados.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'El formato condicional se puede basar en:', 'opcion_multiple', '["Solo el valor de la celda","Otra celda o rango","Solo texto","Solo fechas"]', 'Otra celda o rango', 'Puede usar fórmulas que referencien otras celdas.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Administrar reglas de formato condicional permite:', 'opcion_multiple', '["Solo crear","Editar, eliminar y ordenar reglas","Solo ver","Solo copiar"]', 'Editar, eliminar y ordenar reglas', 'Permite gestionar todas las reglas aplicadas.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Detener si es verdadero en formato condicional:', 'opcion_multiple', '["No existe","Detiene evaluación de reglas siguientes","Siempre evalúa todo","Solo en tablas"]', 'Detiene evaluación de reglas siguientes', 'Cuando es VERDADERO, no evalúa reglas adicionales.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (4, 'La validación de datos permite:', 'opcion_multiple', '["Solo texto","Restringir lo que se puede escribir","Solo números","Solo fechas"]', 'Restringir lo que se puede escribir', 'Restringe el tipo de datos o valores que los usuarios pueden escribir.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (4, 'Una lista de validación crea:', 'opcion_multiple', '["Un gráfico","Una lista desplegable","Una tabla","Un formulario"]', 'Una lista desplegable', 'Crea un menú desplegable con opciones predefinidas.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (4, 'Validación con número entero entre 1 y 10:', 'opcion_multiple', '["No se puede","Permite solo números del 1 al 10","Permite cualquier número","Permite texto"]', 'Permite solo números del 1 al 10', 'Restringe a números enteros dentro del rango especificado.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (4, 'El mensaje de entrada en validación:', 'opcion_multiple', '["No existe","Aparece al seleccionar la celda","Siempre está visible","Solo en impresión"]', 'Aparece al seleccionar la celda', 'Muestra información cuando el usuario selecciona la celda.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (4, 'La alerta de error en validación muestra:', 'opcion_multiple', '["Nada","Mensaje cuando se ingresa dato inválido","Siempre","Solo al guardar"]', 'Mensaje cuando se ingresa dato inválido', 'Aparece cuando el usuario intenta escribir un valor no válido.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (4, 'Validación con fecha posterior a hoy:', 'opcion_multiple', '["No se puede","=HOY()","Solo fechas pasadas","Solo texto"]', '=HOY()', 'Usa fórmula =HOY() para validar fechas futuras.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (4, 'Validación personalizada con fórmula permite:', 'opcion_multiple', '["Solo listas","Cualquier condición lógica","Solo números","Solo texto"]', 'Cualquier condición lógica', 'Permite crear reglas complejas con fórmulas.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (4, 'Circundar datos no válidos muestra:', 'opcion_multiple', '["Nada","Un círculo rojo alrededor","Los elimina","Los oculta"]', 'Un círculo rojo alrededor', 'Dibuja un círculo rojo alrededor de celdas con datos inválidos.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (4, 'Quitar validación de datos:', 'opcion_multiple', '["No se puede","Datos > Validación > Borrar todos","Solo con VBA","Solo borrando celda"]', 'Datos > Validación > Borrar todos', 'Se quita desde Validación de datos > Borrar todos.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (4, 'Validación que depende de otra celda usa:', 'opcion_multiple', '["No se puede","Referencia a otra celda o rango","Solo valores fijos","Solo texto"]', 'Referencia a otra celda o rango', 'Puede usar referencias a otros rangos para listas dependientes.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (4, 'Una macro es:', 'opcion_multiple', '["Una fórmula","Una grabación de acciones automatizadas","Un gráfico","Una tabla"]', 'Una grabación de acciones automatizadas', 'Secuencia de comandos que automatiza tareas repetitivas.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (4, 'Para grabar una macro se usa:', 'opcion_multiple', '["Fórmulas","Programador > Grabar macro","Solo VBA manual","No se puede"]', 'Programador > Grabar macro', 'Pestaña Programador > Grabar macro inicia la grabación.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (4, 'Las macros se guardan en:', 'opcion_multiple', '["Solo en el libro activo","Libro de macros personal o libro actual","Solo en disco","No se guardan"]', 'Libro de macros personal o libro actual', 'Pueden guardarse en el libro actual o en el libro de macros personal.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (4, 'Un botón asignado a macro permite:', 'opcion_multiple', '["No ejecutar","Ejecutar macro con un clic","Solo ver macro","Solo editar"]', 'Ejecutar macro con un clic', 'Ejecuta la macro asignada al hacer clic.', 'avanzado');
