INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (4, 'Power Query sirve para:', 'opcion_multiple', '["Solo gráficos","Transformar y limpiar datos","Solo fórmulas","Solo impresión"]', 'Transformar y limpiar datos', 'Herramienta ETL (Extraer, Transformar, Cargar) de datos.', 'avanzado');
