INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (4, 'Anexar consultas en Power Query:', 'opcion_multiple', '["No se puede","Combina tablas verticalmente","Solo horizontal","Solo copia"]', 'Combina tablas verticalmente', 'Agrega filas de una tabla a otra (unión vertical).', 'avanzado');
