INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (4, 'Cerrar y cargar en Power Query:', 'opcion_multiple', '["No guarda","Aplica transformaciones y carga a Excel","Solo guarda","Solo cierra"]', 'Aplica transformaciones y carga a Excel', 'Ejecuta todas las transformaciones y carga los datos.', 'avanzado');
