INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (4, 'Actualizar desde Power Query:', 'opcion_multiple', '["No actualiza","Refresca datos desde origen","Solo manualmente","Borra datos"]', 'Refresca datos desde origen', 'Actualiza datos desde el origen aplicando transformaciones.', 'avanzado');
