INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (4, 'VF(tasa,nper,pago,va) calcula:', 'opcion_multiple', '["Valor presente","Valor futuro de una inversión","Tasa de interés","Pago periódico"]', 'Valor futuro de una inversión', 'Calcula el valor futuro de una inversión con pagos constantes.', 'avanzado');
