INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (4, 'ENCONTRAR(texto_buscado,dentro_del_texto):', 'opcion_multiple', '["No busca","Posición del texto (sensible a mayúsculas)","Siempre 0","Solo números"]', 'Posición del texto (sensible a mayúsculas)', 'Devuelve posición (distingue mayúsculas/minúsculas).', 'avanzado');
