INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (4, 'FECHA(año,mes,día) crea:', 'opcion_multiple', '["Texto","Una fecha válida","Número","Hora"]', 'Una fecha válida', 'Crea un número de serie de fecha válido.', 'avanzado');
