INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'I _____ to the gym three times a week.', 'opcion_multiple', '["go","am going","went","have gone"]', 'go', 'Present Simple for habits/routines.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'She _____ when I called her.', 'opcion_multiple', '["sleeps","was sleeping","has slept","slept"]', 'was sleeping', 'Past Continuous for action in progress at specific time.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'They _____ in London since 2015.', 'opcion_multiple', '["live","are living","have lived","lived"]', 'have lived', 'Present Perfect with ''since'' for actions from past to present.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'By next year, I _____ my degree.', 'opcion_multiple', '["finish","will finish","will have finished","am finishing"]', 'will have finished', 'Future Perfect for action completed before specific future time.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'If I _____ you, I would accept the offer.', 'opcion_multiple', '["am","was","were","have been"]', 'were', 'Second conditional: ''were'' for hypothetical situations.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'He _____ to work by bus every day.', 'opcion_multiple', '["go","goes","is going","went"]', 'goes', 'Present Simple third person singular: goes.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'I _____ dinner when the phone rang.', 'opcion_multiple', '["cooked","was cooking","have cooked","cook"]', 'was cooking', 'Past Continuous interrupted by Past Simple.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'She _____ never _____ sushi before.', 'opcion_multiple', '["has/eaten","have/eaten","had/eaten","was/eating"]', 'has/eaten', 'Present Perfect for life experience with ''never''.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'While I _____, my brother was watching TV.', 'opcion_multiple', '["studied","was studying","have studied","study"]', 'was studying', 'Two simultaneous actions in past: both Past Continuous.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'The train _____ at 8 PM tonight.', 'opcion_multiple', '["leave","leaves","is leaving","will leave"]', 'leaves', 'Present Simple for scheduled events.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'You _____ wear a helmet when riding a bike.', 'opcion_multiple', '["can","must","might","could"]', 'must', '''Must'' for obligation/necessity.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, '_____ I borrow your pen?', 'opcion_multiple', '["Must","Should","Could","Would"]', 'Could', '''Could'' for polite requests.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'She _____ speak three languages fluently.', 'opcion_multiple', '["must","can","should","would"]', 'can', '''Can'' for ability.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'You _____ see a doctor if you feel sick.', 'opcion_multiple', '["can","should","might","could"]', 'should', '''Should'' for advice.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'It _____ rain later, so take an umbrella.', 'opcion_multiple', '["must","might","should","can"]', 'might', '''Might'' for possibility.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'He _____ have forgotten about the meeting.', 'opcion_multiple', '["must","can","should","will"]', 'must', '''Must have'' for logical deduction about the past.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'You _____ smoke in the hospital.', 'opcion_multiple', '["mustn''t","don''t have to","needn''t","couldn''t"]', 'mustn''t', '''Mustn''t'' for prohibition.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'I _____ finish this report by tomorrow.', 'opcion_multiple', '["can","must","might","could"]', 'must', '''Must'' for strong obligation.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, '_____ you help me with this, please?', 'opcion_multiple', '["Must","Should","Would","Might"]', 'Would', '''Would'' for polite requests.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'You _____ worry, everything will be fine.', 'opcion_multiple', '["mustn''t","needn''t","shouldn''t","couldn''t"]', 'needn''t', '''Needn''t'' for lack of necessity.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'Please _____ your shoes before entering.', 'opcion_multiple', '["take off","put on","get up","turn off"]', 'take off', '''Take off'' = remove.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'I need to _____ early tomorrow.', 'opcion_multiple', '["get up","take off","put on","turn on"]', 'get up', '''Get up'' = wake up and leave bed.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'Can you _____ the lights, please?', 'opcion_multiple', '["turn on","turn off","take off","get up"]', 'turn on', '''Turn on'' = activate.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'She _____ her mother in appearance.', 'opcion_multiple', '["takes after","looks for","gets on","puts up"]', 'takes after', '''Take after'' = resemble (family member).', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'I''m looking _____ to the weekend.', 'opcion_multiple', '["forward","after","for","up"]', 'forward', '''Look forward to'' = anticipate with pleasure.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'He _____ smoking last year.', 'opcion_multiple', '["gave up","gave in","gave out","gave away"]', 'gave up', '''Give up'' = quit/stop doing something.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'Please _____ this form.', 'opcion_multiple', '["fill in","fill up","fill out","fill on"]', 'fill out', '''Fill out'' = complete a form.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'I can''t _____ what he''s saying.', 'opcion_multiple', '["make up","make out","make in","make for"]', 'make out', '''Make out'' = understand/hear clearly.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'She _____ a great idea.', 'opcion_multiple', '["came up with","came across","came into","came from"]', 'came up with', '''Come up with'' = think of/create.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'I _____ an old friend yesterday.', 'opcion_multiple', '["ran into","ran out","ran over","ran away"]', 'ran into', '''Run into'' = meet by chance.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'What is the main cause of climate change according to the text?', 'opcion_multiple', '["Natural cycles","Human activities","Solar radiation","Volcanic activity"]', 'Human activities', 'Text states: ''human activities, particularly burning fossil fuels''.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'What has resulted from rising temperatures?', 'opcion_multiple', '["Only sea level rise","Multiple environmental changes","Only melting ice","Nothing significant"]', 'Multiple environmental changes', 'Text mentions: melting ice caps, rising sea levels, extreme weather.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'What solution does the text suggest?', 'opcion_multiple', '["Ignore the problem","Reduce emissions and use renewable energy","Continue using fossil fuels","Wait for natural solutions"]', 'Reduce emissions and use renewable energy', 'Text states: ''reduce carbon emissions and transition to renewable energy''.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'What is one advantage of remote work?', 'opcion_multiple', '["More isolation","Flexibility","Harder work-life balance","More commuting"]', 'Flexibility', 'Text states: ''offers flexibility and eliminates commuting''.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'What is a disadvantage mentioned?', 'opcion_multiple', '["Too much flexibility","Isolation","No commuting","Too much office time"]', 'Isolation', 'Text mentions: ''challenges such as isolation''.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'What solution are companies adopting?', 'opcion_multiple', '["Only remote work","Only office work","Hybrid models","No work"]', 'Hybrid models', 'Text states: ''adopting hybrid models that combine remote and office work''.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'Synonym of ''happy'':', 'opcion_multiple', '["Sad","Joyful","Angry","Tired"]', 'Joyful', '''Joyful'' means very happy.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'Synonym of ''big'':', 'opcion_multiple', '["Small","Tiny","Large","Little"]', 'Large', '''Large'' means big in size.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'Synonym of ''quick'':', 'opcion_multiple', '["Slow","Fast","Lazy","Late"]', 'Fast', '''Fast'' means quick/rapid.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'Synonym of ''difficult'':', 'opcion_multiple', '["Easy","Simple","Hard","Soft"]', 'Hard', '''Hard'' means difficult.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'Synonym of ''begin'':', 'opcion_multiple', '["End","Finish","Start","Stop"]', 'Start', '''Start'' means begin.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'Synonym of ''important'':', 'opcion_multiple', '["Unimportant","Significant","Minor","Trivial"]', 'Significant', '''Significant'' means important.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'Synonym of ''beautiful'':', 'opcion_multiple', '["Ugly","Attractive","Plain","Ordinary"]', 'Attractive', '''Attractive'' means beautiful/pretty.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'Synonym of ''intelligent'':', 'opcion_multiple', '["Stupid","Smart","Slow","Dull"]', 'Smart', '''Smart'' means intelligent.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'Synonym of ''rich'':', 'opcion_multiple', '["Poor","Wealthy","Broke","Needy"]', 'Wealthy', '''Wealthy'' means rich/having money.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'Synonym of ''famous'':', 'opcion_multiple', '["Unknown","Well-known","Obscure","Anonymous"]', 'Well-known', '''Well-known'' means famous.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'Active: ''They built this house in 1990.'' Passive:', 'opcion_multiple', '["This house built in 1990","This house was built in 1990","This house is built in 1990","This house has built in 1990"]', 'This house was built in 1990', 'Past Simple Passive: was/were + past participle.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'Active: ''Someone stole my bike.'' Passive:', 'opcion_multiple', '["My bike stole","My bike was stolen","My bike is stolen","My bike has stolen"]', 'My bike was stolen', 'Past Simple Passive for unknown agent.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'Active: ''They will announce the results tomorrow.'' Passive:', 'opcion_multiple', '["The results will announce tomorrow","The results will be announced tomorrow","The results are announced tomorrow","The results announce tomorrow"]', 'The results will be announced tomorrow', 'Future Passive: will be + past participle.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'Active: ''People speak English worldwide.'' Passive:', 'opcion_multiple', '["English speaks worldwide","English is spoken worldwide","English was spoken worldwide","English has spoken worldwide"]', 'English is spoken worldwide', 'Present Simple Passive: am/is/are + past participle.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'Active: ''The chef is preparing dinner.'' Passive:', 'opcion_multiple', '["Dinner is preparing","Dinner is being prepared","Dinner was prepared","Dinner prepares"]', 'Dinner is being prepared', 'Present Continuous Passive: is/are being + past participle.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'Active: ''They have completed the project.'' Passive:', 'opcion_multiple', '["The project has completed","The project has been completed","The project was completed","The project completes"]', 'The project has been completed', 'Present Perfect Passive: has/have been + past participle.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'Passive is used when:', 'opcion_multiple', '["The agent is important","The agent is unknown/unimportant","Always use active","Never use passive"]', 'The agent is unknown/unimportant', 'Passive emphasizes the action, not who did it.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, '''By'' in passive voice introduces:', 'opcion_multiple', '["The object","The agent","The time","The place"]', 'The agent', '''By'' introduces who/what performed the action.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'Active: ''You must finish this today.'' Passive:', 'opcion_multiple', '["This must finish today","This must be finished today","This is finished today","This finishes today"]', 'This must be finished today', 'Modal Passive: modal + be + past participle.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'Which is correct passive?', 'opcion_multiple', '["The letter was send","The letter was sent","The letter sent","The letter is send"]', 'The letter was sent', 'Past participle of ''send'' is ''sent''.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'Antonym of ''hot'':', 'opcion_multiple', '["Warm","Cold","Boiling","Heated"]', 'Cold', '''Cold'' is opposite of hot.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'Antonym of ''love'':', 'opcion_multiple', '["Like","Hate","Adore","Cherish"]', 'Hate', '''Hate'' is opposite of love.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'Antonym of ''win'':', 'opcion_multiple', '["Succeed","Lose","Triumph","Achieve"]', 'Lose', '''Lose'' is opposite of win.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (1, 'Antonym of ''always'':', 'opcion_multiple', '["Forever","Never","Often","Usually"]', 'Never', '''Never'' is opposite of always.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'Antonym of ''correct'':', 'opcion_multiple', '["Right","Wrong","Accurate","Precise"]', 'Wrong', '''Wrong'' is opposite of correct.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'Antonym of ''increase'':', 'opcion_multiple', '["Grow","Decrease","Rise","Expand"]', 'Decrease', '''Decrease'' is opposite of increase.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'Antonym of ''accept'':', 'opcion_multiple', '["Agree","Reject","Receive","Approve"]', 'Reject', '''Reject'' is opposite of accept.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'Antonym of ''brave'':', 'opcion_multiple', '["Courageous","Cowardly","Bold","Fearless"]', 'Cowardly', '''Cowardly'' is opposite of brave.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'Antonym of ''generous'':', 'opcion_multiple', '["Kind","Selfish","Giving","Charitable"]', 'Selfish', '''Selfish'' is opposite of generous.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'Antonym of ''arrive'':', 'opcion_multiple', '["Reach","Depart","Come","Enter"]', 'Depart', '''Depart'' is opposite of arrive.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'Zero conditional: If you heat ice, it _____.', 'opcion_multiple', '["melted","melts","will melt","would melt"]', 'melts', 'Zero conditional: If + present, present (facts).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'First conditional: If it rains, I _____ home.', 'opcion_multiple', '["stay","stayed","will stay","would stay"]', 'will stay', 'First conditional: If + present, will + base (real future).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'Second conditional: If I _____ rich, I would travel.', 'opcion_multiple', '["am","was","were","have been"]', 'were', 'Second conditional: If + past, would + base (unreal present).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'Third conditional: If I _____ studied, I would have passed.', 'opcion_multiple', '["have","had","would have","did"]', 'had', 'Third conditional: If + past perfect, would have + past participle (unreal past).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'Mixed conditional: If I _____ harder, I would have a better job now.', 'opcion_multiple', '["worked","had worked","work","would work"]', 'had worked', 'Mixed: past action (had worked) affecting present (would have).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, '''Unless'' means:', 'opcion_multiple', '["If","If not","When","Because"]', 'If not', '''Unless'' = ''if not'' or ''except if''.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'Complete: ''If I were you, I _____ apologize.''', 'opcion_multiple', '["will","would","had","have"]', 'would', 'Second conditional for advice: would + base.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, '''Provided that'' is similar to:', 'opcion_multiple', '["Unless","If","When","Because"]', 'If', '''Provided that'' = ''if'' (on condition that).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'In second conditional, we use ''were'' for:', 'opcion_multiple', '["Only plural","All persons (I/he/she/it)","Only I","Only they"]', 'All persons (I/he/she/it)', '''Were'' is used for all persons in hypothetical situations.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'Third conditional expresses:', 'opcion_multiple', '["Real future","Unreal past (regrets)","Facts","Habits"]', 'Unreal past (regrets)', 'Third conditional: impossible past situations.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'Make a _____', 'opcion_multiple', '["homework","decision","test","class"]', 'decision', '''Make a decision'' (not ''do a decision'').', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'Do your _____', 'opcion_multiple', '["homework","decision","mistake","effort"]', 'homework', '''Do homework'' (not ''make homework'').', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'Take a _____', 'opcion_multiple', '["photo","photo graph","photography","photoed"]', 'photo', '''Take a photo/picture''.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'Have a _____', 'opcion_multiple', '["shower","show","showered","showing"]', 'shower', '''Have a shower'' (British) or ''take a shower'' (American).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'Pay _____', 'opcion_multiple', '["attention","attentive","attentively","attended"]', 'attention', '''Pay attention'' (fixed expression).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'Catch a _____', 'opcion_multiple', '["cold","ill","sick","disease"]', 'cold', '''Catch a cold'' (get sick).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'Break a _____', 'opcion_multiple', '["leg","legged","legging","legs"]', 'leg', '''Break a leg'' (injury or ''good luck'' in theater).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'Keep a _____', 'opcion_multiple', '["secret","secretly","secrete","secrecy"]', 'secret', '''Keep a secret'' (not tell anyone).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'Save _____', 'opcion_multiple', '["time","timing","timed","timer"]', 'time', '''Save time'' (not waste time).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'Waste _____', 'opcion_multiple', '["money","monied","monies","monetary"]', 'money', '''Waste money'' (spend unwisely).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'Direct: ''I am tired.'' Reported: He said he _____ tired.', 'opcion_multiple', '["am","is","was","were"]', 'was', 'Present Simple → Past Simple in reported speech.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'Direct: ''I will call you.'' Reported: She said she _____ call me.', 'opcion_multiple', '["will","would","can","could"]', 'would', 'Will → Would in reported speech.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'Direct: ''I have finished.'' Reported: He said he _____ finished.', 'opcion_multiple', '["have","has","had","having"]', 'had', 'Present Perfect → Past Perfect.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'Direct: ''Can you help?'' Reported: She asked if I _____ help.', 'opcion_multiple', '["can","could","will","would"]', 'could', 'Can → Could in reported speech.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'Direct: ''Where do you live?'' Reported: He asked where I _____.', 'opcion_multiple', '["live","lived","have lived","had lived"]', 'lived', 'Present → Past in reported questions.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'Direct: ''I must go.'' Reported: She said she _____ go.', 'opcion_multiple', '["must","had to","have to","has to"]', 'had to', 'Must → Had to in reported speech.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'Reported speech often uses:', 'opcion_multiple', '["Same tense","Backshift (one tense back)","Future only","Present only"]', 'Backshift (one tense back)', 'Tenses typically shift back in time.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, '''Tomorrow'' in reported speech becomes:', 'opcion_multiple', '["Tomorrow","The next day","Yesterday","Today"]', 'The next day', 'Time expressions change: tomorrow → the next day.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, '''Here'' in reported speech becomes:', 'opcion_multiple', '["Here","There","Everywhere","Nowhere"]', 'There', 'Place expressions: here → there.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'Commands in reported speech use:', 'opcion_multiple', '["Say + infinitive","Tell + object + infinitive","Ask + if","Say + that"]', 'Tell + object + infinitive', '''He told me to go'' (tell + object + to + verb).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'What has AI revolutionized?', 'opcion_multiple', '["Only healthcare","Multiple industries","Only finance","Nothing significant"]', 'Multiple industries', 'Text states: ''numerous industries, from healthcare to finance''.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'What can machine learning do?', 'opcion_multiple', '["Only store data","Analyze data and identify patterns","Delete data","Ignore data"]', 'Analyze data and identify patterns', 'Text: ''analyze vast amounts of data to identify patterns and make predictions''.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'What concerns are mentioned?', 'opcion_multiple', '["Only job displacement","Multiple concerns (jobs, privacy, ethics)","Only privacy","No concerns"]', 'Multiple concerns (jobs, privacy, ethics)', 'Text mentions: ''job displacement, privacy, and ethical implications''.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'What do experts recommend?', 'opcion_multiple', '["Unrestricted AI development","Responsible AI development","Stop AI development","Ignore AI"]', 'Responsible AI development', 'Text: ''need for responsible AI development that prioritizes human welfare''.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'I wish I _____ more time.', 'opcion_multiple', '["have","had","have had","will have"]', 'had', '''I wish'' + past for present regrets.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'I''d rather you _____ now.', 'opcion_multiple', '["leave","left","leaving","will leave"]', 'left', '''I''d rather'' + past for present/future preferences about others.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'It''s time we _____ home.', 'opcion_multiple', '["go","went","going","will go"]', 'went', '''It''s time'' + past for things that should be done now.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'She suggested _____ to the cinema.', 'opcion_multiple', '["go","going","to go","went"]', 'going', '''Suggest'' + gerund (verb-ing).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'He avoided _____ me.', 'opcion_multiple', '["see","seeing","to see","saw"]', 'seeing', '''Avoid'' + gerund.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'I''m looking forward to _____ you.', 'opcion_multiple', '["see","seeing","saw","seen"]', 'seeing', '''Look forward to'' + gerund (to is preposition here).', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'Despite _____ tired, he continued working.', 'opcion_multiple', '["be","being","been","to be"]', 'being', '''Despite'' + gerund/noun.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'In addition to _____ English, she speaks French.', 'opcion_multiple', '["speak","speaking","spoke","spoken"]', 'speaking', '''In addition to'' + gerund.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, 'The book _____ I read was fascinating.', 'opcion_multiple', '["who","which","where","when"]', 'which', '''Which'' for things (relative pronoun).', 'avanzado');
