INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, '''Piece of cake'' means:', 'opcion_multiple', '["Delicious food","Very easy","Very difficult","Expensive"]', 'Very easy', '''Piece of cake'' = very easy task.', 'avanzado');
