INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, '''Once in a blue moon'' means:', 'opcion_multiple', '["Every day","Very rarely","Every month","Often"]', 'Very rarely', '''Once in a blue moon'' = very rarely.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (2, '''The ball is in your court'' means:', 'opcion_multiple', '["Play tennis","Your decision/turn","Sports event","Give up"]', 'Your decision/turn', '''The ball is in your court'' = your responsibility to act.', 'avanzado');
