INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (6, 'Python es un lenguaje:', 'opcion_multiple', '["Compilado","Interpretado","Ensamblador","Máquina"]', 'Interpretado', 'Python es interpretado, se ejecuta línea por línea.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (6, '¿Quién creó Python?', 'opcion_multiple', '["Bill Gates","Guido van Rossum","Steve Jobs","Linus Torvalds"]', 'Guido van Rossum', 'Guido van Rossum lo creó en 1991.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (6, 'La extensión de archivos Python es:', 'opcion_multiple', '[".py",".python",".pt",".p"]', '.py', 'Los archivos Python usan extensión .py', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (6, 'Para imprimir en Python se usa:', 'opcion_multiple', '["echo()","print()","console.log()","write()"]', 'print()', 'print() es la función para mostrar salida.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (6, 'El comentario de una línea en Python usa:', 'opcion_multiple', '["//","#","/* */","--"]', '#', '''#'' inicia un comentario de una línea.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (6, 'Python es sensible a mayúsculas:', 'opcion_multiple', '["No","Sí","Solo en strings","Solo en números"]', 'Sí', 'Python distingue entre mayúsculas y minúsculas.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (6, 'La indentación en Python es:', 'opcion_multiple', '["Opcional","Obligatoria","Solo en funciones","Solo en clases"]', 'Obligatoria', 'La indentación define bloques de código (4 espacios).', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (6, 'Para ejecutar un script Python se usa:', 'opcion_multiple', '["run python.py","python script.py","execute script.py","start script.py"]', 'python script.py', 'python nombre_archivo.py en la terminal.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (6, 'Python 2 y Python 3 son:', 'opcion_multiple', '["Iguales","Incompatibles entre sí","Lo mismo","Solo difieren en nombre"]', 'Incompatibles entre sí', 'Son versiones incompatibles. Python 2 ya no tiene soporte.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (6, 'PEP 8 es:', 'opcion_multiple', '["Una librería","Guía de estilo de Python","Un framework","Un IDE"]', 'Guía de estilo de Python', 'PEP 8 es la guía de estilo oficial de Python.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (6, 'En Python no es necesario declarar:', 'opcion_multiple', '["Funciones","Tipo de variable","Clases","Módulos"]', 'Tipo de variable', 'Python tiene tipado dinámico, no se declara el tipo.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (6, 'x = 5 asigna a x el tipo:', 'opcion_multiple', '["string","int","float","bool"]', 'int', '5 es un número entero (int).', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (6, 'x = 3.14 es tipo:', 'opcion_multiple', '["int","float","decimal","double"]', 'float', 'Números con punto decimal son float.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (6, 'x = "Hola" es tipo:', 'opcion_multiple', '["char","string","str","text"]', 'str', 'En Python se llama str (string).', 'intermedio');
