INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (6, 'El operador de suma es:', 'opcion_multiple', '["+","add","&","sum"]', '+', '+ es el operador de suma.', 'intermedio');
