INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (6, '% es el operador de:', 'opcion_multiple', '["Porcentaje","Módulo (residuo)","División","Multiplicación"]', 'Módulo (residuo)', 'Devuelve el residuo de la división.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (6, '== compara:', 'opcion_multiple', '["Asigna","Igualdad de valor","Identidad","Mayor que"]', 'Igualdad de valor', 'Compara si dos valores son iguales.', 'intermedio');
