INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (6, 'and es operador:', 'opcion_multiple', '["Aritmético","Lógico","Comparación","Asignación"]', 'Lógico', 'Operador lógico Y (ambas deben ser True).', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (6, 'or es operador:', 'opcion_multiple', '["Lógico O","Aritmético","Comparación","Bit a bit"]', 'Lógico O', 'Operador lógico O (al menos una True).', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (6, 'not es operador:', 'opcion_multiple', '["Negación","Afirmación","Multiplicación","División"]', 'Negación', 'Niega un valor booleano.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (6, '+= es:', 'opcion_multiple', '["Asignación simple","Asignación con suma","Comparación","Incremento de 1"]', 'Asignación con suma', 'x += 5 es equivalente a x = x + 5', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (6, 'if se usa para:', 'opcion_multiple', '["Bucles","Condicionales","Funciones","Clases"]', 'Condicionales', 'Ejecuta código si la condición es True.', 'intermedio');
