INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (6, 'lista.sort() ordena:', 'opcion_multiple', '["Descendente","Ascendente","Aleatorio","No ordena"]', 'Ascendente', 'Ordena la lista in-place (ascendente por defecto).', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (6, 'Una tupla es:', 'opcion_multiple', '["Mutable","Inmutable","Solo números","Solo strings"]', 'Inmutable', 'Las tuplas no se pueden modificar después de crearlas.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (6, 'tupla = (1, 2, 3) usa:', 'opcion_multiple', '["Corchetes","Paréntesis","Llaves","Sin nada"]', 'Paréntesis', 'Las tuplas se definen con paréntesis ().', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (6, 'Una tupla de un elemento requiere:', 'opcion_multiple', '["(1)","(1,)","[1]","{1}"]', '(1,)', 'La coma es necesaria: (1,) para diferenciar de expresión.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (6, 'Un conjunto (set) es:', 'opcion_multiple', '["Ordenado","No ordenado y sin duplicados","Con duplicados","Indexado"]', 'No ordenado y sin duplicados', 'Colección no ordenada de elementos únicos.', 'intermedio');
