INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (4, 'La función SI.CONJUNTO evalúa:', 'opcion_multiple', '["Una condición","Múltiples condiciones","Solo texto","Solo números"]', 'Múltiples condiciones', 'Versión mejorada de SI anidado, evalúa múltiples condiciones.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (4, 'SUMAPRODUCTO multiplica y suma:', 'opcion_multiple', '["Matrices o rangos","Solo celdas individuales","Solo texto","Solo fechas"]', 'Matrices o rangos', 'Multiplica componentes de matrices y devuelve la suma.', 'avanzado');
