INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (4, 'La función FILTRAR (FILTER) requiere:', 'opcion_multiple', '["Excel 365/2021+","Excel 2010","Excel 2007","Cualquier versión"]', 'Excel 365/2021+', 'Función dinámica disponible en versiones recientes.', 'avanzado');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (4, 'UNICOS (UNIQUE) devuelve:', 'opcion_multiple', '["Valores duplicados","Valores únicos sin duplicados","La suma","El promedio"]', 'Valores únicos sin duplicados', 'Extrae valores únicos de un rango o matriz.', 'avanzado');
