INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'La retroalimentación constructiva debe ser:', 'opcion_multiple', '["Crítica destructiva","Específica, oportuna y respetuosa","General","Tardía"]', 'Específica, oportuna y respetuosa', 'Feedback específico, en el momento adecuado y de forma respetuosa.', 'intermedio');
