INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'Un conflicto se resuelve mejor con:', 'opcion_multiple', '["Evitación","Diálogo y negociación","Agresión","Imposición"]', 'Diálogo y negociación', 'Comunicación abierta y búsqueda de soluciones mutuamente beneficiosas.', 'intermedio');
