INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'Delegar efectivamente implica:', 'opcion_multiple', '["Solo asignar tareas","Dar autoridad y responsabilidad","Controlar todo","No confiar"]', 'Dar autoridad y responsabilidad', 'Asignar tareas con autoridad, responsabilidad y seguimiento.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'La inteligencia emocional incluye:', 'opcion_multiple', '["Solo IQ","Autoconocimiento, autorregulación, empatía","Solo habilidades técnicas","Solo experiencia"]', 'Autoconocimiento, autorregulación, empatía', 'Capacidad de reconocer y gestionar emociones propias y ajenas.', 'intermedio');
