INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'La toma de decisiones efectiva requiere:', 'opcion_multiple', '["Impulsividad","Análisis de información y alternativas","Solo intuición","Evitar decidir"]', 'Análisis de información y alternativas', 'Proceso estructurado de análisis y evaluación de opciones.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (7, 'Un equipo efectivo tiene:', 'opcion_multiple', '["Solo individuos","Objetivos compartidos y colaboración","Solo competencia","Sin comunicación"]', 'Objetivos compartidos y colaboración', 'Metas comunes, roles definidos y trabajo colaborativo.', 'intermedio');
