INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, '¿Qué función se usa para sumar un rango de celdas?', 'opcion_multiple', '["PROMEDIO","SUMA","CONTAR","MAX"]', 'SUMA', 'La función SUMA agrega todos los números en un rango de celdas.', 'intermedio');
