INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, '¿Qué símbolo se usa para iniciar una fórmula en Excel?', 'opcion_multiple', '["#","=","@","$"]', '=', 'Toda fórmula en Excel comienza con el signo igual (=).', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'La función MAX(B1:B20) devuelve:', 'opcion_multiple', '["El valor mínimo","El valor máximo","El promedio","La suma"]', 'El valor máximo', 'Encuentra el valor más grande en el rango.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Para contar celdas con números se usa:', 'opcion_multiple', '["CONTARA","CONTAR","SUMA","CONTAR.SI"]', 'CONTAR', 'CONTAR cuenta solo celdas que contienen números.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, '¿Qué hace la función MIN?', 'opcion_multiple', '["Suma valores","Encuentra el valor mínimo","Calcula promedio","Cuenta celdas"]', 'Encuentra el valor mínimo', 'Devuelve el valor más pequeño de un rango.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'La fórmula =A1+B1*C1 sigue el orden:', 'opcion_multiple', '["Izquierda a derecha","Multiplicación primero","Suma primero","Aleatorio"]', 'Multiplicación primero', 'Excel sigue el orden PEMDAS: multiplicación antes que suma.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Para calcular el porcentaje de un valor se usa:', 'opcion_multiple', '["*100","/100","*0.01","Todas son correctas"]', '*100', 'Multiplicar por 100 convierte decimal a porcentaje.', 'intermedio');
