INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, '¿Qué función concatena texto?', 'opcion_multiple', '["UNIR","CONCATENAR o &","COMBINAR","TEXTO"]', 'CONCATENAR o &', 'CONCATENAR o el operador & unen texto.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'La función SI(A1>10,"Aprobado","Reprobado") evalúa:', 'opcion_multiple', '["Una condición","Un texto","Una suma","Un promedio"]', 'Una condición', 'SI evalúa una condición lógica y devuelve valores según sea VERDADERO o FALSO.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'BUSCARV busca valores:', 'opcion_multiple', '["En columnas","En filas","En diagonales","En otra hoja"]', 'En columnas', 'BUSCARV (V de vertical) busca en la primera columna de un rango.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Para buscar en horizontal se usa:', 'opcion_multiple', '["BUSCARV","BUSCARH","INDICE","COINCIDIR"]', 'BUSCARH', 'BUSCARH (H de horizontal) busca en filas.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'La función Y() devuelve VERDADERO si:', 'opcion_multiple', '["Todas las condiciones son verdaderas","Alguna es verdadera","Ninguna es verdadera","Una es falsa"]', 'Todas las condiciones son verdaderas', 'Y requiere que todas las condiciones sean verdaderas.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'La función O() devuelve VERDADERO si:', 'opcion_multiple', '["Todas son verdaderas","Al menos una es verdadera","Ninguna es verdadera","Son iguales"]', 'Al menos una es verdadera', 'O devuelve VERDADERO si alguna condición es verdadera.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'SI.ERROR(A1/B1,0) evita:', 'opcion_multiple', '["Errores de división","Errores de texto","Errores de fecha","Todos los errores"]', 'Errores de división', 'Maneja errores, mostrando 0 si hay error (como división por cero).', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'CONTAR.SI(A1:A10,">5") cuenta:', 'opcion_multiple', '["Celdas mayores a 5","Celdas iguales a 5","Celdas menores a 5","Total de celdas"]', 'Celdas mayores a 5', 'Cuenta celdas que cumplen el criterio especificado.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'SUMAR.SI(A1:A10,">10",B1:B10) suma:', 'opcion_multiple', '["A1:A10","B1:B10 donde A>10","Todo el rango","Solo A1:A10"]', 'B1:B10 donde A>10', 'Suma valores de B donde A cumple el criterio.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'La función NO() invierte:', 'opcion_multiple', '["Números","Valores lógicos","Texto","Fechas"]', 'Valores lógicos', 'Convierte VERDADERO en FALSO y viceversa.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Para anidar funciones SI se pueden usar hasta:', 'opcion_multiple', '["3 niveles","7 niveles (versiones antiguas)","64 niveles (Excel 2016+)","Sin límite"]', '64 niveles (Excel 2016+)', 'Excel 2016 y versiones posteriores permiten hasta 64 niveles.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'El formato condicional permite:', 'opcion_multiple', '["Cambiar colores según valores","Eliminar celdas","Copiar fórmulas","Imprimir"]', 'Cambiar colores según valores', 'Aplica formato automáticamente basado en condiciones.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Para resaltar celdas mayores a 100 se usa:', 'opcion_multiple', '["Formato condicional","Formato manual","Filtro","Ordenar"]', 'Formato condicional', 'Formato condicional con regla ''Mayor que''.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Las barras de datos en formato condicional:', 'opcion_multiple', '["Muestran gráficos","Representan visualmente el valor","Suma valores","Promedian"]', 'Representan visualmente el valor', 'Muestran barras proporcionales al valor de la celda.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'La escala de colores muestra:', 'opcion_multiple', '["Valores altos y bajos con colores","Solo valores altos","Solo valores bajos","Texto"]', 'Valores altos y bajos con colores', 'Gradiente de colores según el valor de las celdas.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Los iconos de conjunto muestran:', 'opcion_multiple', '["Flechas, semáforos, etc.","Solo números","Solo texto","Gráficos 3D"]', 'Flechas, semáforos, etc.', 'Indicadores visuales como flechas o semáforos.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Una tabla dinámica sirve para:', 'opcion_multiple', '["Resumir y analizar datos","Solo mostrar datos","Imprimir","Borrar datos"]', 'Resumir y analizar datos', 'Permite resumir, analizar y presentar grandes cantidades de datos.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Para crear una tabla dinámica se usa:', 'opcion_multiple', '["Insertar > Tabla dinámica","Datos > Filtrar","Inicio > Formato","Fórmulas > Insertar"]', 'Insertar > Tabla dinámica', 'Menú Insertar, opción Tabla dinámica.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Los campos de una tabla dinámica se organizan en:', 'opcion_multiple', '["Filas, columnas, valores, filtros","Solo filas","Solo columnas","Celdas"]', 'Filas, columnas, valores, filtros', 'Cuatro áreas: filas, columnas, valores y filtros.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Para actualizar una tabla dinámica se debe:', 'opcion_multiple', '["Actualizar datos y refrescar","Borrar y crear de nuevo","No se puede actualizar","Imprimir"]', 'Actualizar datos y refrescar', 'Cambiar datos origen y hacer clic en ''Actualizar''.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Un gráfico dinámico está vinculado a:', 'opcion_multiple', '["Una tabla dinámica","Datos fijos","Texto","Imágenes"]', 'Una tabla dinámica', 'Se actualiza automáticamente con la tabla dinámica.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'La segmentación de datos permite:', 'opcion_multiple', '["Filtrar visualmente","Sumar valores","Cambiar colores","Imprimir"]', 'Filtrar visualmente', 'Botones interactivos para filtrar tablas dinámicas.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Para agrupar fechas en una tabla dinámica se puede:', 'opcion_multiple', '["Agrupar por meses, trimestres, años","Solo por días","No se puede agrupar","Solo por horas"]', 'Agrupar por meses, trimestres, años', 'Excel permite agrupar fechas en diferentes períodos.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'El campo ''Valores'' en una tabla dinámica generalmente:', 'opcion_multiple', '["Contiene números a calcular","Contiene texto","Contiene fechas","Está vacío"]', 'Contiene números a calcular', 'Área donde se colocan los datos numéricos a resumir.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Para cambiar el cálculo de un campo de valor se usa:', 'opcion_multiple', '["Configuración de campo de valor","Borrar campo","Copiar campo","Mover campo"]', 'Configuración de campo de valor', 'Permite elegir entre suma, promedio, cuenta, etc.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Una tabla dinámica puede obtener datos de:', 'opcion_multiple', '["Rango de Excel, base de datos externa","Solo de Excel","Solo de texto","Solo de internet"]', 'Rango de Excel, base de datos externa', 'Múltiples fuentes de datos son compatibles.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'La validación de datos permite:', 'opcion_multiple', '["Restringir entradas","Borrar datos","Copiar celdas","Imprimir"]', 'Restringir entradas', 'Controla qué tipo de datos se pueden ingresar.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Para crear una lista desplegable se usa:', 'opcion_multiple', '["Validación de datos > Lista","Formato > Lista","Insertar > Lista","Datos > Ordenar"]', 'Validación de datos > Lista', 'Validación de datos con tipo ''Lista''.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Se puede restringir entrada a:', 'opcion_multiple', '["Números, fechas, texto, lista","Solo números","Solo texto","Solo fechas"]', 'Números, fechas, texto, lista', 'Múltiples tipos de validación disponibles.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Un mensaje de entrada en validación:', 'opcion_multiple', '["Aparece al seleccionar celda","Aparece al imprimir","Aparece al guardar","No existe"]', 'Aparece al seleccionar celda', 'Muestra información útil cuando el usuario selecciona la celda.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (3, 'Si se ingresa un dato inválido, Excel puede:', 'opcion_multiple', '["Mostrar advertencia o error","Borrar todo","Cerrar archivo","Imprimir"]', 'Mostrar advertencia o error', 'Muestra mensaje de error configurado.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Un patrón de diapositivas permite:', 'opcion_multiple', '["Solo ver diapositivas","Definir formato global","Borrar diapositivas","Imprimir"]', 'Definir formato global', 'Define el diseño y formato maestro de todas las diapositivas.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Los temas incluyen:', 'opcion_multiple', '["Solo colores","Colores, fuentes y efectos","Solo fuentes","Solo imágenes"]', 'Colores, fuentes y efectos', 'Conjunto coordinado de colores, fuentes, efectos y fondo.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'SmartArt se usa para:', 'opcion_multiple', '["Solo texto","Diagramas y gráficos visuales","Solo imágenes","Solo videos"]', 'Diagramas y gráficos visuales', 'Crea diagramas profesionales (organigramas, procesos, etc.).', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Para insertar un gráfico se usa:', 'opcion_multiple', '["Insertar > Gráfico","Inicio > Gráfico","Datos > Gráfico","Diseño > Gráfico"]', 'Insertar > Gráfico', 'Pestaña Insertar, grupo Ilustraciones, Gráfico.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Una tabla en PowerPoint permite:', 'opcion_multiple', '["Solo texto","Organizar datos en filas y columnas","Solo imágenes","Solo videos"]', 'Organizar datos en filas y columnas', 'Organiza información de manera estructurada.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Los marcadores de posición son:', 'opcion_multiple', '["Imágenes","Áreas reservadas para contenido","Texto fijo","Botones"]', 'Áreas reservadas para contenido', 'Cuadros con bordes punteados que contienen contenido.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Para alinear objetos se usa:', 'opcion_multiple', '["Formato > Alinear","Inicio > Alinear","Insertar > Alinear","Diseño > Alinear"]', 'Formato > Alinear', 'Herramientas de alineación en pestaña Formato.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Agrupar objetos permite:', 'opcion_multiple', '["Solo ver","Tratar múltiples objetos como uno","Borrar","Imprimir"]', 'Tratar múltiples objetos como uno', 'Combina varios objetos para moverlos/formatearlos juntos.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'La regla en PowerPoint muestra:', 'opcion_multiple', '["Solo texto","Medidas y guías","Solo imágenes","Solo colores"]', 'Medidas y guías', 'Ayuda a posicionar objetos con precisión.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Las guías son:', 'opcion_multiple', '["Líneas no imprimibles de alineación","Texto","Imágenes","Botones"]', 'Líneas no imprimibles de alineación', 'Líneas punteadas que ayudan a alinear objetos.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Las animaciones de entrada:', 'opcion_multiple', '["Sacan objetos","Hacen aparecer objetos","Cambian color","Borran"]', 'Hacen aparecer objetos', 'Hacen que los objetos aparezcan en la diapositiva.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Las animaciones de énfasis:', 'opcion_multiple', '["Hacen desaparecer","Llaman la atención sobre objeto existente","Mueven objeto","Borran"]', 'Llaman la atención sobre objeto existente', 'Resaltan objetos ya visibles (pulsar, girar, etc.).', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Las animaciones de salida:', 'opcion_multiple', '["Hacen aparecer","Hacen desaparecer objetos","Mueven","Cambian color"]', 'Hacen desaparecer objetos', 'Hacen que los objetos desaparezcan de la diapositiva.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Las rutas de animación:', 'opcion_multiple', '["Solo cambian color","Mueven objetos por trayectoria","Borran objetos","Solo texto"]', 'Mueven objetos por trayectoria', 'Mueven objetos a lo largo de una trayectoria definida.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'El panel de animación muestra:', 'opcion_multiple', '["Solo texto","Todas las animaciones de la diapositiva","Solo imágenes","Solo colores"]', 'Todas las animaciones de la diapositiva', 'Lista todas las animaciones con su orden y configuración.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Iniciar animación ''Al hacer clic'' significa:', 'opcion_multiple', '["Automática","Requiere clic del mouse","Con teclado","Con sonido"]', 'Requiere clic del mouse', 'La animación comienza al hacer clic.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Iniciar ''Con la anterior'' significa:', 'opcion_multiple', '["Requiere clic","Inicia simultáneamente con animación anterior","Inicia después","No inicia"]', 'Inicia simultáneamente con animación anterior', 'Se ejecuta al mismo tiempo que la animación previa.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Iniciar ''Después de la anterior'' significa:', 'opcion_multiple', '["Requiere clic","Inicia automáticamente después","Inicia antes","No inicia"]', 'Inicia automáticamente después', 'Comienza automáticamente al terminar la anterior.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'La duración de animación controla:', 'opcion_multiple', '["Solo color","Cuánto tiempo tarda","Solo tamaño","Solo posición"]', 'Cuánto tiempo tarda', 'Tiempo que toma completar la animación.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'El retraso en animación:', 'opcion_multiple', '["No existe","Tiempo de espera antes de iniciar","Duración","Velocidad"]', 'Tiempo de espera antes de iniciar', 'Pausa antes de que comience la animación.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Animar modelos 3D permite:', 'opcion_multiple', '["Solo ver","Rotación y movimiento 3D","Solo texto","Solo color"]', 'Rotación y movimiento 3D', 'Animaciones específicas para objetos 3D.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Morph (Transformación) es una transición que:', 'opcion_multiple', '["Solo cambia color","Anima transformaciones entre diapositivas","Borra","Imprime"]', 'Anima transformaciones entre diapositivas', 'Crea animación suave entre objetos similares en diapositivas consecutivas.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Las transiciones son:', 'opcion_multiple', '["Animaciones entre diapositivas","Animaciones dentro de diapositiva","Solo texto","Solo imágenes"]', 'Animaciones entre diapositivas', 'Efectos visuales al pasar de una diapositiva a otra.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Para aplicar transición a todas las diapositivas se usa:', 'opcion_multiple', '["Aplicar a todas","Solo a una","No se puede","Manual"]', 'Aplicar a todas', 'Botón ''Aplicar a todas'' en pestaña Transiciones.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'El sonido en transiciones:', 'opcion_multiple', '["No existe","Se puede agregar","Solo en videos","Solo en música"]', 'Se puede agregar', 'Se puede añadir efecto de sonido a la transición.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Avanzar diapositiva ''Automáticamente después'' significa:', 'opcion_multiple', '["Requiere clic","Cambia sola después de tiempo","No cambia","Imprime"]', 'Cambia sola después de tiempo', 'Cambia automáticamente tras el tiempo especificado.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Para insertar video se usa:', 'opcion_multiple', '["Insertar > Video","Inicio > Video","Datos > Video","Diseño > Video"]', 'Insertar > Video', 'Pestaña Insertar, grupo Multimedia.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Para insertar audio se usa:', 'opcion_multiple', '["Insertar > Audio","Inicio > Audio","Datos > Audio","Diseño > Audio"]', 'Insertar > Audio', 'Pestaña Insertar, grupo Multimedia, Audio.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Los hipervínculos permiten:', 'opcion_multiple', '["Solo ver","Navegar a otras diapositivas o URLs","Solo texto","Solo imágenes"]', 'Navegar a otras diapositivas o URLs', 'Enlaces a otras partes de la presentación o web.', 'intermedio');
INSERT INTO preguntas (habilidad_id, pregunta, tipo, opciones, respuesta_correcta, explicacion, dificultad) VALUES (5, 'Las acciones de botón permiten:', 'opcion_multiple', '["Solo ver","Interactividad (ejecutar programas, macros)","Solo texto","Solo imágenes"]', 'Interactividad (ejecutar programas, macros)', 'Botones interactivos con acciones asignadas.', 'intermedio');
